package cli

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/runnerdefaults"

	"charm.land/huh/v2"
)

// ensureRunnersPresent scaffolds the default runner set when a repo has none
// yet, so `tune` doubles as onboarding. It returns the IDs it created (nil when
// runners already existed) so the caller can flag any that tuning then leaves
// un-tailored. It is a no-op when runners already exist, and errors when the
// user declined or creation failed. Writing is gated on confirmation
// (interactive prompt, or the --yes flag for non-interactive runs).
func ensureRunnersPresent(w, errW io.Writer, repoRoot string, assumeYes bool) (created []string, err error) {
	dir := runnersDir(repoRoot)
	existing, _ := filepath.Glob(filepath.Join(dir, "*.json")) //nolint:errcheck // bad pattern only; treated as "none found"
	if len(existing) > 0 {
		return nil, nil
	}

	defaults, err := runnerdefaults.Files()
	if err != nil {
		return nil, fmt.Errorf("loading default runners: %w", err)
	}

	if !assumeYes {
		if !interactive.CanPromptInteractively() {
			return nil, fmt.Errorf("no runner configs found under %s; re-run with --yes to create the default set (%d runners)", dir, len(defaults))
		}
		confirmed, err := confirmCreateRunners(len(defaults))
		if err != nil {
			return nil, err
		}
		if !confirmed {
			return nil, errors.New("no runner configs created (declined)")
		}
	}

	if err := os.MkdirAll(dir, 0o755); err != nil { //nolint:gosec // config dir, conventional perms
		return nil, fmt.Errorf("creating %s: %w", dir, err)
	}
	for _, f := range defaults {
		dest := filepath.Join(dir, f.Name)
		if err := os.WriteFile(dest, f.Data, 0o644); err != nil { //nolint:gosec // runner configs are repo-committed, world-readable config
			return nil, fmt.Errorf("writing %s: %w", dest, err)
		}
		fmt.Fprintf(w, "created %s\n", filepath.Join(paths.EntireDir, "runners", f.Name))
		created = append(created, strings.TrimSuffix(f.Name, ".json"))
	}
	fmt.Fprintf(errW, "Created %d default runner(s); tailoring them to this repo…\n", len(defaults))
	return created, nil
}

func confirmCreateRunners(n int) (bool, error) {
	var ok bool
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("No trail runners found. Create the default set (%d runners) in .entire/runners/?", n)).
				Description("Written from the built-in defaults, then tailored to this repo.").
				Value(&ok),
		),
	)
	if err := form.Run(); err != nil {
		return false, fmt.Errorf("runner-creation prompt cancelled: %w", err)
	}
	return ok, nil
}

// confirmTuneExisting asks whether to re-tailor runners that already exist —
// the re-run case where there is nothing to scaffold.
func confirmTuneExisting() (bool, error) {
	var ok bool
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Runners are already configured for this repo. Tune them to this repo now?").
				Description("Re-tailors the runner prompts using fresh repository signal.").
				Value(&ok),
		),
	)
	if err := form.Run(); err != nil {
		return false, fmt.Errorf("runner-tune prompt cancelled: %w", err)
	}
	return ok, nil
}
package cli

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/spf13/cobra"
)

type runnerSetupOptions struct {
	runner       string // optional: limit to one runner (id, with or without "trail-")
	run          bool   // headless apply vs. print prompt
	assumeYes    bool   // skip the create-defaults confirmation
	debugDir     string // if set, dump prompt.txt (+ response.txt on --run) here
	sources      []string
	limit        int
	insecureHTTP bool
}

func newRunnerSetupCmd() *cobra.Command {
	var (
		run       bool
		assumeYes bool
		debugDir  string
		sources   []string
		limit     int
	)

	cmd := &cobra.Command{
		Use:   "setup [<runner>]",
		Short: "Create and tailor this repository's trail runners",
		Long: `Set up the .entire/runners/*.json evaluators for this repository.

Runners (risk, confidence, drift, security, review, …) score and review a
branch's changes. The shipped templates are generic; "setup" tailors them to
THIS repo using gathered signal — its docs and structure, merged PRs and
issues, checkpoint churn hotspots, and past trail findings.

- In a repo with no runners, setup creates the default set first (use --yes to
  skip the confirmation), then tailors them.
- Run again in a repo that already has runners and setup offers to re-tune them.

By default setup prints the tailoring prompt to stdout, ready to paste into
your agent. With --run it executes the prompt headlessly through your
configured summary provider and rewrites the runner files in place (review with
git diff).

If <runner> is given (e.g. "risk" or "trail-risk"), only that runner is tuned.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			runner := ""
			if len(args) == 1 {
				runner = args[0]
			}
			return runRunnerSetup(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), runnerSetupOptions{
				runner:       runner,
				run:          run,
				assumeYes:    assumeYes,
				debugDir:     debugDir,
				sources:      sources,
				limit:        limit,
				insecureHTTP: runnerInsecureHTTP(cmd),
			})
		},
	}

	cmd.Flags().BoolVar(&run, "run", false,
		"Run the configured summary provider headlessly to rewrite the runner files in place (default: print the prompt)")
	cmd.Flags().StringSliceVar(&sources, "sources", nil,
		"Comma-separated data sources to gather: repo, prs, checkpoints, trails, all (default: all)")
	cmd.Flags().IntVar(&limit, "limit", 20, "How many recent PRs/issues/trails to sample")
	cmd.Flags().BoolVarP(&assumeYes, "yes", "y", false,
		"Skip the confirmation when creating the default runner set in a repo that has none")
	cmd.Flags().StringVar(&debugDir, "debug-dir", "",
		"Write the assembled prompt (prompt.txt) and, with --run, the raw model response (response.txt) to this directory for debugging")

	return cmd
}

func runRunnerSetup(ctx context.Context, w, errW io.Writer, opts runnerSetupOptions) error {
	src, err := parseTuneSources(opts.sources)
	if err != nil {
		return err
	}

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	// A repo with no runners gets the default set scaffolded (on confirmation),
	// which setup then tailors below.
	created, err := ensureRunnersPresent(w, errW, repoRoot, opts.assumeYes)
	if err != nil {
		return err
	}

	// Re-run on an already-configured repo: setup is done, so offer to re-tune
	// rather than silently re-emitting. --run is taken as an explicit yes.
	if len(created) == 0 && !opts.run {
		if !interactive.CanPromptInteractively() {
			fmt.Fprintln(errW, "Runners already configured. Re-run with --run to tailor them headlessly.")
			return nil
		}
		proceed, err := confirmTuneExisting()
		if err != nil {
			return err
		}
		if !proceed {
			fmt.Fprintln(errW, "Runners already configured. Nothing to do.")
			return nil
		}
	}

	runners, err := loadTuneRunners(repoRoot, opts.runner)
	if err != nil {
		return err
	}

	stopGather := startSpinner(errW, "Gathering repository signal")
	brief := gatherTuningContext(ctx, errW, repoRoot, src, opts.limit, opts.insecureHTTP)
	stopGather(true)
	prompt := buildTunePrompt(brief, runners)

	if opts.debugDir != "" {
		writeTuneDebug(errW, opts.debugDir, "prompt.txt", prompt)
	}

	if !opts.run {
		fmt.Fprintln(w, prompt)
		if len(created) > 0 {
			fmt.Fprintf(errW, "\nCreated %d working default runner(s) (untracked). They are functional as-is; paste the prompt above into your agent to tailor them to this repo.\n", len(created))
		}
		fmt.Fprintf(errW, "\n%d runner(s) in scope. Paste the prompt above into your agent, or re-run with --run to apply headlessly.\n", len(runners))
		return nil
	}

	return applyTuneWithAgent(ctx, w, errW, runners, prompt, created, opts.debugDir)
}

// writeTuneDebug best-effort writes content to <dir>/<name> for debugging,
// reporting any failure as a warning rather than failing the command.
func writeTuneDebug(errW io.Writer, dir, name, content string) {
	if err := os.MkdirAll(dir, 0o755); err != nil { //nolint:gosec // user-specified debug dir
		fmt.Fprintf(errW, "warning: debug dir %s: %v\n", dir, err)
		return
	}
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil { //nolint:gosec // local debug artifact
		fmt.Fprintf(errW, "warning: writing %s: %v\n", path, err)
		return
	}
	fmt.Fprintf(errW, "debug: wrote %s\n", path)
}

// applyTuneWithAgent runs the prompt through the configured summary provider
// (prompt -> text), parses the runner-id -> template map it returns, and
// surgically rewrites each runner file's prompt.template in place. createdIDs
// are runners onboarding just scaffolded from defaults; any of those left
// un-tailored is flagged so it isn't committed as if it were repo-specific.
func applyTuneWithAgent(ctx context.Context, w, errW io.Writer, runners []tuneRunner, prompt string, createdIDs []string, debugDir string) error {
	// Reuse the summary-provider resolution (selection + persistence), but pull
	// the raw TextGenerator rather than provider.Generator: the latter is a
	// summarize.Generator that turns a transcript Input into a checkpoint
	// Summary, whereas we need plain prompt->text generation here.
	provider, err := resolveCheckpointSummaryProvider(ctx, errW)
	if err != nil {
		return err
	}
	ag, err := agent.Get(provider.Name)
	if err != nil {
		return fmt.Errorf("loading provider %s: %w", provider.Name, err)
	}
	textGen, ok := agent.AsTextGenerator(ag)
	if !ok {
		return fmt.Errorf("provider %s cannot generate text", provider.Name)
	}

	stop := startSpinner(errW, fmt.Sprintf("Tuning %d runner(s) with %s", len(runners), provider.DisplayName))
	out, err := textGen.GenerateText(ctx, prompt, provider.Model)
	stop(err == nil)
	if err != nil {
		return fmt.Errorf("agent run failed: %w", err)
	}
	if debugDir != "" {
		writeTuneDebug(errW, debugDir, "response.txt", out)
	}

	templates, err := parseTuneOutput(out)
	if err != nil {
		return err
	}

	byID := make(map[string]tuneRunner, len(runners))
	for _, r := range runners {
		byID[normalizeRunnerID(r.ID)] = r
	}

	updated, skipped := 0, 0
	tailored := make(map[string]bool)
	for id, tmpl := range templates {
		r, ok := byID[normalizeRunnerID(id)]
		if !ok {
			fmt.Fprintf(errW, "skip %q: not a runner in scope\n", id)
			skipped++
			continue
		}
		if err := validateNewTemplate(r.Template, tmpl); err != nil {
			fmt.Fprintf(errW, "skip %s: %v\n", r.ID, err)
			skipped++
			continue
		}
		if dropped := droppedPlaceholders(r.Template, tmpl); len(dropped) > 0 {
			fmt.Fprintf(errW, "note: %s no longer references %v\n", r.ID, dropped)
		}
		newRaw, err := replaceRunnerTemplate(r.Raw, tmpl)
		if err != nil {
			fmt.Fprintf(errW, "skip %s: %v\n", r.ID, err)
			skipped++
			continue
		}
		if bytes.Equal(newRaw, r.Raw) {
			continue // model returned the current template verbatim — benign no-op
		}
		if err := os.WriteFile(r.Path, newRaw, 0o644); err != nil { //nolint:gosec // runner configs are repo-committed, world-readable config
			return fmt.Errorf("writing %s: %w", r.Path, err)
		}
		fmt.Fprintf(w, "updated %s\n", filepath.Base(r.Path))
		tailored[normalizeRunnerID(r.ID)] = true
		updated++
	}

	switch {
	case updated > 0:
		fmt.Fprintf(w, "\nUpdated %d runner(s). Review with: git diff .entire/runners\n", updated)
	case len(createdIDs) == 0 && skipped > 0:
		// Existing runners, model proposed templates, all rejected — a failed run.
		// (When onboarding just created the set, an un-tailored runner is reported
		// below as a generic default instead, which is more actionable.)
		return fmt.Errorf("model proposed %d template(s) but all were rejected or out of scope (see messages above)", skipped)
	case len(createdIDs) == 0:
		fmt.Fprintln(w, "No runner changes proposed.")
	}

	// Runners onboarding scaffolded but tuning didn't tailor remain the generic
	// defaults. Those are working minimal prompts (valid output contract), so
	// they're committable as-is — just note which are still generic.
	if untailored := untailoredRunners(createdIDs, tailored); len(untailored) > 0 {
		fmt.Fprintf(errW, "\n%d runner(s) kept as working defaults (generic, not tailored to this repo): %s\n",
			len(untailored), strings.Join(untailored, ", "))
		fmt.Fprintln(errW, "They are functional as-is; re-run `entire runner setup --run` to tailor them.")
	}
	return nil
}
package cli

import (
	"fmt"

	"github.com/spf13/cobra"
)

// newRunnerCmd is the root of the `entire runner` group, which manages the
// trail runner configs under .entire/runners/. Hidden during maturation, like
// the related `trail` group.
func newRunnerCmd() *cobra.Command {
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:    "runner",
		Short:  "Set up and tune trail runners for this repository",
		Hidden: true,
		Args:   cobra.NoArgs,
		Long: `Manage the trail runner configs in .entire/runners/.

Runners are the per-repo evaluators (risk, confidence, drift, security, review,
…) that score and review a branch's changes. Use ` + "`entire runner setup`" + ` to
create the default set in a repo that has none, and to tailor the runner
prompts to this repository.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return cmd.Help()
		},
	}

	cmd.PersistentFlags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
		"Allow API calls over plain HTTP (insecure, for local development only)")
	if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
	}

	cmd.AddCommand(newRunnerSetupCmd())

	return cmd
}

// runnerInsecureHTTP reads the persistent --insecure-http-auth flag from the
// runner root command.
func runnerInsecureHTTP(cmd *cobra.Command) bool {
	v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
	return v
}
package cli

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// parseTuneOutput extracts the runner-id -> new-template map the tuning model
// is instructed to emit as a single JSON object. The model may wrap the object
// in prose or code fences, so we slice from the first "{" to the last "}". An
// empty object ({}) is valid: the model is told to omit unchanged runners, so
// "{}" is the legitimate "no changes" result, not an error.
func parseTuneOutput(text string) (map[string]string, error) {
	obj := extractJSONObject(text)
	if obj == "" {
		return nil, errors.New("no JSON object found in model output")
	}
	var m map[string]string
	if err := json.Unmarshal([]byte(obj), &m); err != nil {
		return nil, fmt.Errorf("parse model output as {runner: template}: %w", err)
	}
	return m, nil
}

var placeholderRe = regexp.MustCompile(`{{[^{}]+}}`)

// validateNewTemplate rejects a rewritten template that is empty or that
// introduces a {{placeholder}} not present in the original. An invented
// placeholder is unsafe: the backend only substitutes the known set, so a new
// token renders as literal "{{junk}}" in the prompt. Dropping a placeholder is
// safe — it just leaves a substitution slot unused (e.g. the model commonly
// drops the cosmetic {{branch}} since the diff is taken against HEAD) — so
// drops are allowed here and surfaced as a note by the caller instead.
func validateNewTemplate(oldTemplate, newTemplate string) error {
	if strings.TrimSpace(newTemplate) == "" {
		return errors.New("rewritten template is empty")
	}
	oldSet := placeholderSet(oldTemplate)
	var added []string
	for ph := range placeholderSet(newTemplate) {
		if !oldSet[ph] {
			added = append(added, ph)
		}
	}
	sort.Strings(added)
	if len(added) > 0 {
		return fmt.Errorf("rewritten template added unknown placeholder(s): %s", strings.Join(added, ", "))
	}
	return nil
}

// untailoredRunners returns the created runner IDs that tuning did NOT tailor
// (still generic defaults), sorted. These were scaffolded by onboarding but
// left unchanged — skipped, omitted by the model, or returned verbatim — so
// they must not be presented as repo-tailored.
func untailoredRunners(createdIDs []string, tailored map[string]bool) []string {
	var out []string
	for _, id := range createdIDs {
		if !tailored[normalizeRunnerID(id)] {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

// droppedPlaceholders returns the placeholders present in oldTemplate but not in
// newTemplate, sorted. Used to inform the user when a rewrite stops using one.
func droppedPlaceholders(oldTemplate, newTemplate string) []string {
	newSet := placeholderSet(newTemplate)
	var dropped []string
	for ph := range placeholderSet(oldTemplate) {
		if !newSet[ph] {
			dropped = append(dropped, ph)
		}
	}
	sort.Strings(dropped)
	return dropped
}

func placeholderSet(s string) map[string]bool {
	set := make(map[string]bool)
	for _, ph := range placeholderRe.FindAllString(s, -1) {
		set[ph] = true
	}
	return set
}

// extractJSONObject returns the outermost {...} span in text, after stripping
// any surrounding markdown code fences. Returns "" when none is found.
func extractJSONObject(text string) string {
	text = stripCodeFences(strings.TrimSpace(text))
	start := strings.Index(text, "{")
	end := strings.LastIndex(text, "}")
	if start < 0 || end <= start {
		return ""
	}
	return text[start : end+1]
}

func stripCodeFences(text string) string {
	if !strings.HasPrefix(text, "```") {
		return text
	}
	// Drop the opening fence line (``` or ```json) and the closing fence.
	if nl := strings.IndexByte(text, '\n'); nl >= 0 {
		text = text[nl+1:]
	}
	if i := strings.LastIndex(text, "```"); i >= 0 {
		text = text[:i]
	}
	return strings.TrimSpace(text)
}

// replaceRunnerTemplate swaps only the prompt.template value inside a runner
// JSON document, leaving every other field and the file's formatting
// byte-for-byte intact. It works on the raw bytes (not a re-marshal) so unknown
// or backend-managed fields are never dropped and the git diff stays scoped to
// the prompt change. Returns the original bytes unchanged when newTemplate
// matches the current template.
func replaceRunnerTemplate(raw []byte, newTemplate string) ([]byte, error) {
	var top map[string]json.RawMessage
	if err := json.Unmarshal(raw, &top); err != nil {
		return nil, fmt.Errorf("parse runner JSON: %w", err)
	}
	promptRaw, ok := top["prompt"]
	if !ok {
		return nil, errors.New("runner has no \"prompt\" object")
	}
	var promptObj map[string]json.RawMessage
	if err := json.Unmarshal(promptRaw, &promptObj); err != nil {
		return nil, fmt.Errorf("parse runner prompt object: %w", err)
	}
	// oldVal holds the original on-disk bytes of the template value, so it is a
	// guaranteed substring of raw.
	oldVal, ok := promptObj["template"]
	if !ok {
		return nil, errors.New("runner has no \"prompt.template\" field")
	}

	newVal, err := encodeJSONString(newTemplate)
	if err != nil {
		return nil, err
	}
	if bytes.Equal(oldVal, newVal) {
		return raw, nil
	}

	if n := bytes.Count(raw, oldVal); n != 1 {
		return nil, fmt.Errorf("expected exactly one occurrence of the current template, found %d", n)
	}
	out := bytes.Replace(raw, oldVal, newVal, 1)
	if !json.Valid(out) {
		return nil, errors.New("template replacement produced invalid JSON")
	}
	return out, nil
}

// encodeJSONString encodes s as a JSON string without HTML escaping, so
// characters like <, >, and & stay literal — matching the style the runner
// files are authored in and keeping diffs minimal.
func encodeJSONString(s string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return nil, fmt.Errorf("encode template string: %w", err)
	}
	return bytes.TrimRight(buf.Bytes(), "\n"), nil
}

