import { z } from "zod"

import { githubRepoProvider } from "../repo-provider"
import { isValidCronExpression } from "./cron-schedule"
import { listGithubDirectoryJsonPaths } from "./github-contents"
import { CODE_REVIEW_COMMENTS_RESULT_TYPE } from "./review-output"

const RUNNERS_DIR = ".entire/runners"
export const RUNNER_CONFIG_REF = "main"
const RUNNER_ID_PATTERN = /^[a-zA-Z0-9_-]+$/
const MAX_RUNNER_ID_LENGTH = 64
const MAX_RUNNER_RESULT_TYPE_LENGTH = 128
// Cap the per-runner sandbox TTL so a typo can't pin a sandbox alive far longer
// than any agent could need (the old global default was 60 min).
const MAX_SANDBOX_AUTO_STOP_MINUTES = 60

const runnerOutputAdapters = ["json", "last_json_line", "markdown", "score"] as const
const runnerContextProviders = ["trail", "github.checks"] as const
const trailMonitorValueTypes = ["percent", "size", "boolean"] as const
const trailMonitorPolarities = ["higher_is_better", "lower_is_better", "neutral"] as const
const runnerCheckFilters = ["fixable_failures"] as const
const runnerRepoTokenPermissions = ["read", "write"] as const
const runnerSandboxCheckouts = ["repo", "none"] as const

export type RunnerOutputAdapter = (typeof runnerOutputAdapters)[number]
export type RunnerContextProvider = (typeof runnerContextProviders)[number]
export type RunnerCheckFilter = (typeof runnerCheckFilters)[number]
export type RunnerRepoTokenPermission = (typeof runnerRepoTokenPermissions)[number]
export type RunnerSandboxCheckout = (typeof runnerSandboxCheckouts)[number]

const optionalStringOrNullSchema = z.string().nullable().optional()
const nonBlankStringSchema = z.string().refine((value) => value.trim().length > 0)
const runnerIdSchema = z.string().max(MAX_RUNNER_ID_LENGTH).regex(RUNNER_ID_PATTERN)
const resultTypeSchema = z.string().max(MAX_RUNNER_RESULT_TYPE_LENGTH).nullable().optional()
const trailMonitorKeySchema = z
  .string()
  .max(64)
  .regex(/^[a-zA-Z0-9_-]+$/)
// Bounded to the repo_trail_monitor_results.label column (varchar(128)) so an
// over-long label fails fast at config load instead of at insert time.
const trailMonitorLabelSchema = z
  .string()
  .max(128)
  .refine((value) => value.trim().length > 0)
const timeoutMsSchema = z.number().int().positive()
const runnerExtraArgsSchema = z.array(z.string())
// Write access is requested through git_push so its guarded, branch-only
// semantics are explicit. repo_token remains read-only configuration; the
// internal permission type still includes write for sandbox provisioning.
const configuredRepoTokenPermissionSchema = z.literal("read")

const sandboxSchema = z
  .object({
    repo_token: configuredRepoTokenPermissionSchema.nullable().optional(),
    git_push: z.boolean().optional(),
    checkout: z.enum(runnerSandboxCheckouts).optional(),
    auto_stop_minutes: z
      .number()
      .int()
      .positive()
      .max(MAX_SANDBOX_AUTO_STOP_MINUTES)
      .nullable()
      .optional(),
  })
  .passthrough()

const automationSchema = z
  .object({
    kind: nonBlankStringSchema,
    prompt_builder: optionalStringOrNullSchema,
  })
  .passthrough()

const outputSchema = z
  .object({
    format: z.enum(["last_json_line", "none"]).optional(),
    adapter: z.enum(runnerOutputAdapters).optional(),
    result_type: resultTypeSchema,
    score_field: optionalStringOrNullSchema,
    trail_field: z.enum(["body"]).nullable().optional(),
    trail_monitor: z
      .object({
        key: trailMonitorKeySchema,
        label: trailMonitorLabelSchema,
        value_type: z.enum(trailMonitorValueTypes),
        polarity: z.enum(trailMonitorPolarities).optional(),
      })
      .passthrough()
      .nullable()
      .optional(),
  })
  .passthrough()
  .superRefine((output, ctx) => {
    const adapter = output.adapter ?? output.format ?? null
    if (!adapter) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: "output adapter is required" })
      return
    }
    if (adapter !== "none" && (!output.result_type || output.result_type.trim() === "")) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: "output result_type is required" })
    }
    if (adapter === "score" && (!output.score_field || output.score_field.trim() === "")) {
