      .optional(),
    context: z.array(z.enum(runnerContextProviders)).optional(),
    output: outputSchema.optional(),
    sandbox: sandboxSchema.optional(),
    schedule: z.string().optional(),
    debounce_ms: z.number().int().nonnegative().optional(),
    trails_review: z
      .object({
        enabled: z.boolean(),
      })
      .passthrough()
      .optional(),
  })
  .passthrough()

const runnerFlatConfigSchema = runnerCommonConfigSchema.extend({
  agent: nonBlankStringSchema,
  timeout_ms: timeoutMsSchema,
  automation: automationSchema,
  runtime: z.never().optional(),
})

const runnerPromptRunnerConfigSchema = runnerCommonConfigSchema.extend({
  agent: optionalStringOrNullSchema,
  timeout_ms: timeoutMsSchema.nullable().optional(),
  automation: automationSchema.optional(),
  runtime: z
    .object({
      kind: z.literal("prompt_runner"),
