const runnerInlineConfigSchema = runnerCommonConfigSchema.extend({
  agent: optionalStringOrNullSchema,
  timeout_ms: z.number().finite().nullable().optional(),
  automation: automationSchema,
  runtime: z
    .object({
      kind: z.literal("inline"),
    })
    .passthrough(),
})

export const runnerConfigSchema = z
  .union([
    runnerInlineConfigSchema,
    runnerPromptRunnerConfigSchema,
    runnerCommandRunnerConfigSchema,
