export interface NormalizedRunnerOutputConfig {
  adapter: RunnerOutputAdapter | "none"
  resultType: string | null
  scoreField: string | null
  trailField: "body" | null
  trailMonitor: NormalizedTrailMonitorOutputConfig | null
}

function normalizeOutputAdapter(
  output: RunnerConfigFile["output"],
): RunnerOutputAdapter | "none" | null {
  if (!output) return null
  if (output.adapter) return output.adapter
  if (output.format === "none") return "none"
  if (output.format === "last_json_line") return "last_json_line"
  return null
}

function getPromptTemplate(prompt: RunnerConfigFile["prompt"]): string | null {
  if (typeof prompt === "string") return prompt
  if (prompt && typeof prompt === "object" && typeof prompt.template === "string") {
    return prompt.template
  }
  return null
}

export function getRunnerConfigPath(id: string): string {
  return `${RUNNERS_DIR}/${id.replaceAll("_", "-")}.json`
}

export function isValidRunnerId(id: string): boolean {
  return id.length <= MAX_RUNNER_ID_LENGTH && RUNNER_ID_PATTERN.test(id)
}

export function isValidRunnerConfig(value: unknown): value is RunnerConfigFile {
  return runnerConfigSchema.safeParse(value).success
}

export function normalizeRunnerOutput(
  output: RunnerConfigFile["output"],
): NormalizedRunnerOutputConfig | null {
  const adapter = normalizeOutputAdapter(output) ?? null
  const trailMonitor = output?.trail_monitor
  return adapter
    ? {
        adapter,
        resultType: output?.result_type?.trim() || null,
        scoreField: output?.score_field?.trim() || null,
        trailField: output?.trail_field ?? null,
        trailMonitor: trailMonitor
          ? {
              key: trailMonitor.key,
              label: trailMonitor.label,
              valueType: trailMonitor.value_type,
              polarity: trailMonitor.polarity ?? "neutral",
            }
          : null,
      }
    : null
}

